vec4 c = vec4( 5.0 ,0.4,0.15,0.1);
uv2 = uv + vec2( 1.0 , 0.0 )*(vec2(1.0)/uTexSize);
float gx1 = GetPixel(uv2)*c.x + GetBlur1(uv2).xy*c.y + GetBlur2(uv2)*c.z + GetBlur3(uv2)*c.w;
uv2 = uv + vec2(-1, 0.0 )*(vec2(1.0)/uTexSize);
float gx2 = GetPixel(uv2)*c.x + GetBlur1(uv2).xy*c.y + GetBlur2(uv2)*c.z + GetBlur3(uv2)*c.w;
uv2 = uv + vec2( 0.0 , 1.0 )*(vec2(1.0)/uTexSize);
float gy1 = GetPixel(uv2)*c.x + GetBlur1(uv2).xy*c.y + GetBlur2(uv2)*c.z + GetBlur3(uv2)*c.w;
uv2 = uv + vec2( 0.0 ,-1)*(vec2(1.0)/uTexSize);
float gy2 = GetPixel(uv2)*c.x + GetBlur1(uv2).xy*c.y + GetBlur2(uv2)*c.z + GetBlur3(uv2)*c.w;
vec3 g = normalize(vec3(gx1-gx2, gy1-gy2, 0.14));
ret = 0.5 + 0.5*g;
ret *= clamp01(length(ret.xy-0.5) * 5.0);
ret = ret.xxy;
ret += 1.15;
ret *= mix(ret,ret*(GetBlur3(uv)-GetBlur1(uv).xy*audioHighSmooth / 3.0),pow(hue_shader.xzy,audioLowSmooth / 3.0));
ret *= ret;
//ret *= 1.5; //old gamma effect
}
  fragColor = vec4(ret, 1.0);
}

